<script setup>import {computed,onMounted,reactive,ref} from 'vue';import api from '../api';import {useAuthStore} from '../stores/auth';import {ElMessage,ElMessageBox} from 'element-plus';const auth=useAuthStore(),manager=computed(()=>['LAB_ADMIN','SYSTEM_ADMIN'].includes(auth.user?.role)),list=ref([]),devices=ref([]),visible=ref(false);const form=reactive({deviceId:null,faultDesc:'',severity:'MEDIUM',remark:''});const labels={PENDING:'待受理',PROCESSING:'处理中',COMPLETED:'已完成',CLOSED:'已关闭'},types={PENDING:'warning',PROCESSING:'primary',COMPLETED:'success',CLOSED:'info'},severity={LOW:'轻微',MEDIUM:'一般',HIGH:'严重'};async function load(){list.value=(await api.get(manager.value?'/manage/repairs':'/repairs/my')).data}async function submit(){await api.post('/repairs',form);visible.value=false;ElMessage.success('报修工单已提交');await load()}async function handle(row,status){let result='';if(status==='COMPLETED')result=(await ElMessageBox.prompt('请填写维修处理结果','完成维修',{inputValidator:v=>!!v||'处理结果不能为空'})).value;await api.put(`/manage/repairs/${row.id}/handle`,{status,result});ElMessage.success('工单状态已更新');await load()}onMounted(async()=>{const [deviceResponse]=await Promise.all([api.get('/devices'),load()]);devices.value=deviceResponse.data});</script>
<template><div class="page"><div class="page-head"><div><h2 class="page-title">{{manager?'维修工单':'故障报修'}}</h2><div class="page-sub">记录设备故障、处理进度和维修结果</div></div><el-button v-if="!manager" type="primary" @click="visible=true"><Plus/>提交报修</el-button></div><div class="panel"><el-table :data="list"><el-table-column prop="deviceName" label="设备" min-width="150"><template #default="s"><b>{{s.row.deviceName}}</b></template></el-table-column><el-table-column v-if="manager" prop="reporterName" label="报修人" width="110"/><el-table-column prop="faultDesc" label="故障现象" min-width="220"/><el-table-column label="影响程度" width="100"><template #default="s">{{severity[s.row.severity]}}</template></el-table-column><el-table-column prop="createdAt" label="报修时间" width="170"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="types[s.row.status]">{{labels[s.row.status]}}</el-tag></template></el-table-column><el-table-column prop="result" label="处理结果" min-width="150"/><el-table-column v-if="manager" label="操作" width="170"><template #default="s"><el-button v-if="s.row.status==='PENDING'" link type="primary" @click="handle(s.row,'PROCESSING')">受理</el-button><el-button v-if="s.row.status==='PROCESSING'" link type="success" @click="handle(s.row,'COMPLETED')">完成维修</el-button><el-button v-if="!['COMPLETED','CLOSED'].includes(s.row.status)" link type="info" @click="handle(s.row,'CLOSED')">关闭</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" title="提交设备报修" width="540"><el-form label-width="90px"><el-form-item label="故障设备"><el-select v-model="form.deviceId" filterable style="width:100%"><el-option v-for="x in devices" :key="x.id" :label="`${x.name} · ${x.deviceCode}`" :value="x.id"/></el-select></el-form-item><el-form-item label="影响程度"><el-radio-group v-model="form.severity"><el-radio-button v-for="(v,k) in severity" :key="k" :value="k">{{v}}</el-radio-button></el-radio-group></el-form-item><el-form-item label="故障现象"><el-input v-model="form.faultDesc" type="textarea" :rows="4" placeholder="请描述故障发生时的现象"/></el-form-item><el-form-item label="补充说明"><el-input v-model="form.remark"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="submit">提交工单</el-button></template></el-dialog></div></template>
